-- 1. one table to you, 24 chunks underneath: one per hour of data
SELECT count(*) AS chunks FROM show_chunks('auth_latency');

-- 2. a question about 09:00 to 10:00 only opens the chunk that holds that hour
EXPLAIN (COSTS OFF)
SELECT avg(latency_ms) FROM auth_latency
WHERE time >= '2026-11-07 09:00+00' AND time < '2026-11-07 10:00+00';

-- 3. downsample: M-0042's latency in 5-minute buckets, 09:00 to 09:30
SELECT time_bucket('5 minutes', time) AS bucket, count(*) AS n,
       round(avg(latency_ms)::numeric, 1) AS avg_ms, round(max(latency_ms)::numeric) AS max_ms
FROM auth_latency
WHERE merchant_id = 'M-0042' AND time >= '2026-11-07 09:00+00' AND time < '2026-11-07 09:30+00'
GROUP BY bucket ORDER BY bucket;

-- 4. a continuous aggregate: hourly summaries per merchant, kept by TimescaleDB
CREATE MATERIALIZED VIEW latency_hourly WITH (timescaledb.continuous) AS
SELECT time_bucket('1 hour', time) AS bucket, merchant_id,
       count(*) AS n, sum(latency_ms) AS sum_ms, max(latency_ms) AS max_ms
FROM auth_latency GROUP BY bucket, merchant_id;
SELECT count(*) AS hourly_rows FROM latency_hourly;

-- 5. retention: drop the raw chunks from before 18:00; the hourly summaries stay
SELECT count(*) AS chunks_dropped FROM drop_chunks('auth_latency', older_than => TIMESTAMPTZ '2026-11-07 18:00+00');
SELECT count(*) AS raw_rows FROM auth_latency;
SELECT count(*) AS hourly_rows, sum(n) AS points_summarised FROM latency_hourly;

-- 1. exact search: compare query 1 with every one of the 100,000 vectors
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF)
SELECT id FROM items ORDER BY embedding <-> (SELECT embedding FROM queries WHERE id = 1) LIMIT 10;

-- the true top 10 of every query, by brute force (no index exists yet)
CREATE TEMP TABLE truth AS
SELECT q.id AS qid, i.id
FROM queries q CROSS JOIN LATERAL (SELECT id FROM items ORDER BY embedding <-> q.embedding LIMIT 10) i;

-- 2. build an HNSW index (pgvector's defaults: m = 16, ef_construction = 64)
\timing on
CREATE INDEX items_hnsw ON items USING hnsw (embedding vector_l2_ops);
\timing off

-- 3. the same query, through the index
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF)
SELECT id FROM items ORDER BY embedding <-> (SELECT embedding FROM queries WHERE id = 1) LIMIT 10;

-- 4. recall@10: what share of the true top 10 does the index find, at three beam widths?
CREATE TEMP VIEW recall AS
SELECT current_setting('hnsw.ef_search') AS ef_search, round(avg(found) / 10.0, 3) AS recall_at_10
FROM (SELECT q.id, count(t.id) AS found
      FROM queries q
      CROSS JOIN LATERAL (SELECT id FROM items ORDER BY embedding <-> q.embedding LIMIT 10) a
      LEFT JOIN truth t ON t.qid = q.id AND t.id = a.id
      GROUP BY q.id) r;
SET hnsw.ef_search = 10;  SELECT * FROM recall;
SET hnsw.ef_search = 40;  SELECT * FROM recall;
SET hnsw.ef_search = 200; SELECT * FROM recall;

